public_declarations:
def sparseSignedLabelMeasure (α : ℝ) (x : ℕ → ℝ) (N : ℕ → ℕ) : Measure (ℕ × Bool) :=
  (sparseLabelMeasure α x N).prod
    (Measure.sum (fun b : Bool => (1 / 2 : ℝ≥0∞) • Measure.dirac b))

def sparseSignedAmplitude (α : ℝ) (x : ℕ → ℝ) (N : ℕ → ℕ) (z : ℕ × Bool) : ℝ :=
  if z.2 = true then sparseLevelAmplitude α x N z.1
  else -sparseLevelAmplitude α x N z.1

def sparseSignedShift (α : ℝ) (x : ℕ → ℝ) (N : ℕ → ℕ) (z : ℕ × Bool) : ℝ :=
  if z.2 = true then sparseLevelShift α x N z.1
  else -sparseLevelShift α x N z.1
